begin;
create schema pt;
create function pt.ok(v boolean,label text) returns void language plpgsql as $$ begin if v is distinct from true then raise exception 'ASSERT %',label;end if;end $$;
create function pt.no(cmd text,label text) returns void language plpgsql as $$ begin begin execute cmd;exception when others then return;end;raise exception 'ACCEPTED %',label;end $$;
grant usage on schema pt to authenticated,service_role;grant execute on all functions in schema pt to authenticated,service_role;
insert into auth.users values('10000000-0000-4000-8000-000000000001','admin'),('10000000-0000-4000-8000-000000000002','creator'),('10000000-0000-4000-8000-000000000003','viewer'),('10000000-0000-4000-8000-000000000004','outsider');
insert into public.profiles(id,email,status) select id,email,'active' from auth.users;
insert into public.user_roles values('10000000-0000-4000-8000-000000000001','Admin'),('10000000-0000-4000-8000-000000000002','Admin'),('10000000-0000-4000-8000-000000000002','PR Leader'),('10000000-0000-4000-8000-000000000003','Viewer'),('10000000-0000-4000-8000-000000000004','PR Leader');
insert into public.marketing_teams(id,name,creator_id) values('20000000-0000-4000-8000-000000000001','A','10000000-0000-4000-8000-000000000001');
insert into public.marketing_team_memberships(team_id,user_id) select '20000000-0000-4000-8000-000000000001',id from auth.users where email<>'outsider';
insert into public.marketing_campaigns(id,team_id,name,kind,creator_id,status,official_kpis,activated_by,activated_at) values('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Campaign','seasonal','10000000-0000-4000-8000-000000000001','active','[]','10000000-0000-4000-8000-000000000001',now());
insert into public.marketing_content_items(id,campaign_id,team_id,creator_id,title,content_line,publishing_status) values('40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002','Content','Sharing','in_review');
select pt.ok(not has_function_privilege('authenticated','public.marketing_publishing_gateway_command(jsonb)','execute'),'no user gateway');
select pt.ok(not has_function_privilege('authenticated','marketing_private.publishing_gateway_command(jsonb)','execute'),'no private gateway');
select pt.ok(not has_table_privilege('service_role','public.marketing_publishing_jobs','update'),'no direct service writes');
select pt.ok(not has_table_privilege('authenticated','marketing_private.publishing_credentials','select'),'no credentials');
select pt.ok(not (select prosecdef from pg_proc where oid='public.marketing_publishing_gateway_command(jsonb)'::regprocedure),'public invoker');
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select set_config('pt.connection',public.marketing_publishing_gateway_command(jsonb_build_object('action','save_connection','actor_id','10000000-0000-4000-8000-000000000001','team_id','20000000-0000-4000-8000-000000000001','page_id','12345','page_name','Fixture','graph_version','test-only','capabilities','{"read_posts":true,"read_comments":false,"organic_metrics":false,"upload_media":true,"publish":true,"schedule":true,"cancel":true}'::jsonb,'verified_at',to_char(now(),'YYYY-MM-DD"T"HH24:MI:SS"Z"'),'expires_at',null,'credential_ciphertext','opaque-encrypted-fixture','verification_reference','local-fixture'))::text,true);
select pt.ok(not(current_setting('pt.connection')::jsonb ? 'credential_ciphertext'),'safe connection');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select pt.no($q$select public.marketing_publishing_gateway_command('{"action":"claim_job","worker_id":"user","lease_seconds":30}')$q$,'user cannot claim even spoofed jwt role');
select set_config('pt.request',jsonb_build_object('action','request_candidate','content_id','40000000-0000-4000-8000-000000000001','expected_content_version',1,'connection_id',current_setting('pt.connection')::jsonb->>'id','mode','text','design_id',null,'final_asset_ids','[]'::jsonb,'scheduled_for',to_char(now()+interval '10 minutes','YYYY-MM-DD"T"HH24:MI:SS"Z"'))::text,true);
select pt.no($q$select public.marketing_publishing_command(current_setting('pt.request')::jsonb||'{"sha256":"fake"}')$q$,'reject client hash field');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',true);
select pt.no($q$select public.marketing_publishing_command(current_setting('pt.request')::jsonb)$q$,'outsider');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select pt.no($q$select public.marketing_publishing_command(current_setting('pt.request')::jsonb)$q$,'viewer');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select set_config('pt.candidate',public.marketing_publishing_command(current_setting('pt.request')::jsonb)::text,true);
set local role service_role;
select set_config('pt.candidate',public.marketing_publishing_gateway_command(jsonb_build_object('action','seal_candidate','id',current_setting('pt.candidate')::jsonb->>'id','expected_version',1,'media','[]'::jsonb))::text,true);
select pt.ok(length(current_setting('pt.candidate')::jsonb->>'payload_hash')=64,'SHA seal');
select pt.no($q$select public.marketing_publishing_gateway_command(jsonb_build_object('action','seal_candidate','id',current_setting('pt.candidate')::jsonb->>'id','expected_version',2,'media','[]'::jsonb))$q$,'no reseal');
set local role authenticated;
-- A replacement at a different time must retire the old sealed candidate.
select set_config('pt.old_candidate',current_setting('pt.candidate'),true);
select set_config('pt.candidate',public.marketing_publishing_command(current_setting('pt.request')::jsonb||jsonb_build_object('scheduled_for',to_char(now()+interval '20 minutes','YYYY-MM-DD"T"HH24:MI:SS"Z"')))::text,true);
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select pt.no($q$select public.marketing_publishing_command(jsonb_build_object('action','approve_and_schedule','id',current_setting('pt.old_candidate')::jsonb->>'id','expected_version',2,'expected_hash',current_setting('pt.old_candidate')::jsonb->>'payload_hash','confirmed',true))$q$,'superseded sealed candidate cannot approve');
set local role service_role;
select set_config('pt.candidate',public.marketing_publishing_gateway_command(jsonb_build_object('action','seal_candidate','id',current_setting('pt.candidate')::jsonb->>'id','expected_version',1,'media','[]'::jsonb))::text,true);
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select set_config('pt.approve',jsonb_build_object('action','approve_and_schedule','id',current_setting('pt.candidate')::jsonb->>'id','expected_version',2,'expected_hash',current_setting('pt.candidate')::jsonb->>'payload_hash','confirmed',true)::text,true);
select pt.no($q$select public.marketing_publishing_command(current_setting('pt.approve')::jsonb)$q$,'multirole Admin creator cannot self approve');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select public.marketing_publishing_command(current_setting('pt.approve')::jsonb);
select pt.no($q$select public.marketing_publishing_command(current_setting('pt.approve')::jsonb)$q$,'duplicate approval');
select pt.ok((select count(*)=1 from public.marketing_publishing_jobs),'atomic unique job');
select pt.ok((select publishing_status='approved' from public.marketing_content_items),'internal approval not remote schedule');
set local role service_role;
select pt.ok(public.marketing_publishing_gateway_command('{"action":"claim_job","worker_id":"fixture","lease_seconds":30}') is null,'future job not claimable');
reset role;
update public.marketing_publishing_jobs set scheduled_for=now()-interval '1 minute',next_attempt_at=now()-interval '1 minute';
set local role service_role;
select set_config('pt.job',public.marketing_publishing_gateway_command('{"action":"claim_job","worker_id":"fixture","lease_seconds":30}')::text,true);
select pt.no($q$select public.marketing_publishing_gateway_command(jsonb_build_object('action','begin_dispatch','id',current_setting('pt.job')::jsonb->>'id','lease_id','99999999-0000-4000-8000-000000000001'))$q$,'wrong lease');
select set_config('pt.dispatch',public.marketing_publishing_gateway_command(jsonb_build_object('action','inspect_job','id',current_setting('pt.job')::jsonb->>'id','lease_id',current_setting('pt.job')::jsonb->>'lease_id'))::text,true);
select pt.ok(current_setting('pt.dispatch')::jsonb->'job'->>'status'='claimed','inspect does not start remote');
select public.marketing_publishing_gateway_command(jsonb_build_object('action','begin_dispatch','id',current_setting('pt.job')::jsonb->>'id','lease_id',current_setting('pt.job')::jsonb->>'lease_id'));
select pt.no($q$select public.marketing_publishing_gateway_command(jsonb_build_object('action','complete_job','id',current_setting('pt.job')::jsonb->>'id','lease_id',current_setting('pt.job')::jsonb->>'lease_id','outcome','published','remote_id','123','receipt','{}'::jsonb,'error',null))$q$,'unverified success rejected');
reset role;
update public.marketing_publishing_jobs set lease_until=now()-interval '1 second';
set local role service_role;
select pt.ok(public.marketing_publishing_gateway_command('{"action":"claim_job","worker_id":"second","lease_seconds":30}') is null,'expired remote start never retried');
set local role authenticated;
select pt.ok((select status='unknown' from public.marketing_publishing_jobs),'expired dispatch unknown');
select set_config('pt.job',(select to_jsonb(j)::text from public.marketing_publishing_jobs j),true);
select set_config('pt.incident',(select to_jsonb(i)::text from public.marketing_publishing_incidents i limit 1),true);
select public.marketing_publishing_command(jsonb_build_object('action','acknowledge_incident','id',current_setting('pt.incident')::jsonb->>'id','expected_version',1,'reason','Investigating'));
select pt.no($q$select public.marketing_publishing_command(jsonb_build_object('action','resolve_incident','id',current_setting('pt.incident')::jsonb->>'id','expected_version',2,'reason','Claim resolved'))$q$,'acknowledgment not risk resolution');
set local role service_role;
select set_config('pt.job',public.marketing_publishing_gateway_command(jsonb_build_object('action','reconcile_job','id',current_setting('pt.job')::jsonb->>'id','expected_version',(current_setting('pt.job')::jsonb->>'version')::int,'outcome','remote_scheduled','remote_id','123','receipt','{"verified":true}'::jsonb))::text,true);
reset role;
update public.marketing_campaigns set status='emergency_hold',version=version+1;
select pt.ok((select status='cancel_pending' from public.marketing_publishing_jobs),'hold remote scheduled needs cancel');
update public.marketing_campaigns set status='active',version=version+1;
select pt.ok((select status='cancel_pending' from public.marketing_publishing_jobs),'resume never requeues');
select pt.ok((select cancel_requested_at is not null from public.marketing_publishing_jobs),'durable cancellation intent');
select set_config('pt.job',(select to_jsonb(j)::text from public.marketing_publishing_jobs j),true);
set local role service_role;
select pt.no($q$select public.marketing_publishing_gateway_command(jsonb_build_object('action','reconcile_job','id',current_setting('pt.job')::jsonb->>'id','expected_version',(current_setting('pt.job')::jsonb->>'version')::int,'outcome','cancelled','remote_id','999','receipt','{"verified":true,"state":"cancelled","remote_id":"999"}'::jsonb))$q$,'different remote object cannot resolve cancellation');
select pt.no($q$select public.marketing_publishing_gateway_command(jsonb_build_object('action','reconcile_job','id',current_setting('pt.job')::jsonb->>'id','expected_version',(current_setting('pt.job')::jsonb->>'version')::int,'outcome','cancelled','remote_id','123','receipt','{"verified":true,"state":"published","remote_id":"123","cancelled":true}'::jsonb))$q$,'receipt state mismatch');
select set_config('pt.job',public.marketing_publishing_gateway_command(jsonb_build_object('action','reconcile_job','id',current_setting('pt.job')::jsonb->>'id','expected_version',(current_setting('pt.job')::jsonb->>'version')::int,'outcome','unknown','remote_id','123','receipt','{}'::jsonb))::text,true);
select pt.ok(current_setting('pt.job')::jsonb->>'cancel_requested_at' is not null,'timeout retains cancellation intent');
select set_config('pt.job',public.marketing_publishing_gateway_command(jsonb_build_object('action','reconcile_job','id',current_setting('pt.job')::jsonb->>'id','expected_version',(current_setting('pt.job')::jsonb->>'version')::int,'outcome','remote_scheduled','remote_id','123','receipt','{"verified":true,"state":"remote_scheduled","remote_id":"123"}'::jsonb))::text,true);
select pt.ok(current_setting('pt.job')::jsonb->>'status'='cancel_pending','scheduled discovery respects earlier cancel intent');
select set_config('pt.cancel_marker',current_setting('pt.job')::jsonb->>'cancel_requested_at',true);
select pt.no($q$select public.marketing_publishing_gateway_command(jsonb_build_object('action','reconcile_job','id',current_setting('pt.job')::jsonb->>'id','expected_version',(current_setting('pt.job')::jsonb->>'version')::int,'outcome','cancelled','remote_id','123','receipt','{"verified":true,"state":"cancelled","remote_id":"999"}'::jsonb))$q$,'receipt object differs from command identity');
select set_config('pt.job',public.marketing_publishing_gateway_command(jsonb_build_object('action','reconcile_job','id',current_setting('pt.job')::jsonb->>'id','expected_version',(current_setting('pt.job')::jsonb->>'version')::int,'outcome','failed','remote_id','123','receipt','{"verified":false,"state":"failed","remote_id":"123"}'::jsonb))::text,true);
select pt.ok(current_setting('pt.job')::jsonb->>'status'='cancel_pending' and current_setting('pt.job')::jsonb->>'cancel_requested_at'=current_setting('pt.cancel_marker'),'failed cancellation retains first intent and pending risk');

reset role;

select set_config('pt.job',(select to_jsonb(j)::text from public.marketing_publishing_jobs j),true);
set local role service_role;
select pt.no($q$select public.marketing_publishing_gateway_command(jsonb_build_object('action','reconcile_job','id',current_setting('pt.job')::jsonb->>'id','expected_version',(current_setting('pt.job')::jsonb->>'version')::int,'outcome','cancelled','remote_id','123','receipt','{"verified":true}'::jsonb))$q$,'cancellation explicit outcome required');
select public.marketing_publishing_gateway_command(jsonb_build_object('action','reconcile_job','id',current_setting('pt.job')::jsonb->>'id','expected_version',(current_setting('pt.job')::jsonb->>'version')::int,'outcome','cancelled','remote_id','123','receipt','{"verified":true,"cancelled":true}'::jsonb));
reset role;
select pt.no($q$update public.marketing_publication_candidates set snapshot='{}'$q$,'immutable sealed snapshot after approval');
select pt.ok((select count(*)>=2 from public.marketing_revisions),'status history appended');
-- A second publication exercises actual byte attestations and revoked-reference gates.
insert into public.marketing_content_items(id,campaign_id,team_id,creator_id,title,content_line,publishing_status) values('40000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002','Photo','Sharing','in_review');
insert into public.marketing_assets(id,team_id,title,filename,mime_type,byte_size,width,height,reported_sha256,storage_path,status,provenance,author,event,tags,rights,allowed_channels,creator_id) values('50000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Photo','photo.png','image/png',123,1080,1080,repeat('a',64),'fixture/photo.png','ready','owned','creator','','{}','approved','{facebook}','10000000-0000-4000-8000-000000000002');
set local role authenticated;
select set_config('pt.request',(current_setting('pt.request')::jsonb||jsonb_build_object('content_id','40000000-0000-4000-8000-000000000002','mode','photo_dump','final_asset_ids',jsonb_build_array('50000000-0000-4000-8000-000000000001')))::text,true);
select set_config('pt.candidate',public.marketing_publishing_command(current_setting('pt.request')::jsonb)::text,true);
set local role service_role;
select pt.no($q$select public.marketing_publishing_gateway_command(jsonb_build_object('action','seal_candidate','id',current_setting('pt.candidate')::jsonb->>'id','expected_version',1,'media','[]'::jsonb))$q$,'missing bytes attestation');
select set_config('pt.media',jsonb_build_array(jsonb_build_object('asset_id','50000000-0000-4000-8000-000000000001','asset_version',1,'byte_size',123,'sha256',repeat('b',64)))::text,true);
select set_config('pt.candidate',public.marketing_publishing_gateway_command(jsonb_build_object('action','seal_candidate','id',current_setting('pt.candidate')::jsonb->>'id','expected_version',1,'media',current_setting('pt.media')::jsonb))::text,true);
select pt.ok(current_setting('pt.candidate')::jsonb->'snapshot'->'media'->0->>'sha256'=repeat('b',64),'actual attestation differs from client reported digest');
select pt.ok(not(current_setting('pt.candidate')::jsonb->'snapshot'->'assets'->0 ? 'reported_sha256'),'reported digest excluded');
reset role;
update public.marketing_assets set rights='revoked',version=version+1;
set local role authenticated;
select pt.no($q$select public.marketing_publishing_command(jsonb_build_object('action','approve_and_schedule','id',current_setting('pt.candidate')::jsonb->>'id','expected_version',2,'expected_hash',current_setting('pt.candidate')::jsonb->>'payload_hash','confirmed',true))$q$,'rights revoked before review');
reset role;
update public.marketing_assets set rights='approved',version=version+1;
set local role authenticated;
select pt.no($q$select public.marketing_publishing_command(jsonb_build_object('action','approve_and_schedule','id',current_setting('pt.candidate')::jsonb->>'id','expected_version',2,'expected_hash',current_setting('pt.candidate')::jsonb->>'payload_hash','confirmed',true))$q$,'old candidate cannot revive with rights restored');
select set_config('pt.candidate',public.marketing_publishing_command(current_setting('pt.request')::jsonb)::text,true);
set local role service_role;
select set_config('pt.media',jsonb_set(current_setting('pt.media')::jsonb,'{0,asset_version}','3')::text,true);
select set_config('pt.candidate',public.marketing_publishing_gateway_command(jsonb_build_object('action','seal_candidate','id',current_setting('pt.candidate')::jsonb->>'id','expected_version',1,'media',current_setting('pt.media')::jsonb))::text,true);
set local role authenticated;
select public.marketing_publishing_command(jsonb_build_object('action','approve_and_schedule','id',current_setting('pt.candidate')::jsonb->>'id','expected_version',2,'expected_hash',current_setting('pt.candidate')::jsonb->>'payload_hash','confirmed',true));
reset role;
update public.marketing_publishing_jobs set scheduled_for=now()-interval '1 minute',next_attempt_at=now()-interval '1 minute' where status='queued';
set local role service_role;
select set_config('pt.job',public.marketing_publishing_gateway_command('{"action":"claim_job","worker_id":"fixture","lease_seconds":30}')::text,true);
reset role;
update public.marketing_publishing_jobs set lease_until=now()-interval '1 second' where status='claimed';
set local role service_role;
select public.marketing_publishing_gateway_command('{"action":"claim_job","worker_id":"fixture","lease_seconds":30}');
reset role;
select pt.ok((select status='queued' and remote_started_at is null from public.marketing_publishing_jobs where content_id='40000000-0000-4000-8000-000000000002'),'expired prewrite lease bounded retry');
update public.marketing_publishing_jobs set next_attempt_at=now()-interval '1 minute' where status='queued';
set local role service_role;
select set_config('pt.job',public.marketing_publishing_gateway_command('{"action":"claim_job","worker_id":"fixture","lease_seconds":30}')::text,true);
reset role;
update public.marketing_campaigns set status='emergency_hold',version=version+1;
select pt.ok((select status='cancelled' from public.marketing_publishing_jobs where content_id='40000000-0000-4000-8000-000000000002'),'hold claimed before remote safely cancelled');
update public.marketing_campaigns set status='active',version=version+1;
select pt.ok((select status='cancelled' from public.marketing_publishing_jobs where content_id='40000000-0000-4000-8000-000000000002'),'resume leaves cancelled job terminal');
rollback;
